def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def norm_list(v):
        return v if isinstance(v, list) else (v or [])

    def step_towards(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    sh = observation.get("grid_height", 0) or 0
    sw = observation.get("grid_width", 0) or 0
    self_p = (sx, sy)
    opp_p = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_towards(self_p, opp_p)
        corners = [
            (0, 0),
            (0, max(0, sh - 1)),
            (max(0, sw - 1), 0),
            (max(0, sw - 1), max(0, sh - 1)),
        ]
        target = max(corners, key=lambda c: manhattan(c, opp_p) - manhattan(c, self_p) * 0.1)
        return step_towards(self_p, target)

    if env == "territory_control":
        targets = norm_list(observation.get("unclaimed_cells"))
        if not targets:
            targets = norm_list(observation.get("opponent_territory"))
        if not targets:
            targets = norm_list(observation.get("neutral_cells"))
        if not targets:
            cx, cy = (sw - 1) // 2 if sw else sx, (sh - 1) // 2 if sh else sy
            return step_towards(self_p, (cx, cy))
        best = min(
            targets,
            key=lambda item: (manhattan(self_p, pos(item)), manhattan(opp_p, pos(item)))
        )
        return step_towards(self_p, pos(best))

    resources = norm_list(observation.get("resources"))
    if resources:
        best = min(
            resources,
            key=lambda item: (manhattan(self_p, pos(item)), manhattan(opp_p, pos(item)) * 0.5)
        )
        return step_towards(self_p, pos(best))

    # Fallbacks for missing/empty resource maps
    if sw and sh:
        cx, cy = (sw - 1) // 2, (sh - 1) // 2
        if self_p != (cx, cy):
            return step_towards(self_p, (cx, cy))

    return step_towards(self_p, opp_p)

